// The categories, exactly as GraphVis 17 grouped them. A flat list of eighty
// four names is not a choice anyone can make.
inline const QVector<QPair<QString,QStringList>>& categories(){
    static const QVector<QPair<QString,QStringList>> cats{
        {QStringLiteral("Perceptually Uniform"),{QStringLiteral("Parula"),QStringLiteral("Viridis"),QStringLiteral("Plasma"),QStringLiteral("Inferno"),QStringLiteral("Magma"),QStringLiteral("Cividis"),QStringLiteral("Turbo")}},
        {QStringLiteral("Scientific Sequential"),{QStringLiteral("Hot"),QStringLiteral("Afmhot"),QStringLiteral("Gist Heat"),QStringLiteral("Copper"),QStringLiteral("Bone"),QStringLiteral("Pink"),QStringLiteral("Gray"),QStringLiteral("Greys"),QStringLiteral("Purples"),QStringLiteral("Blues"),QStringLiteral("Greens"),QStringLiteral("Oranges"),QStringLiteral("Reds"),QStringLiteral("YlOrBr"),QStringLiteral("YlOrRd"),QStringLiteral("OrRd"),QStringLiteral("PuRd"),QStringLiteral("RdPu"),QStringLiteral("BuPu"),QStringLiteral("GnBu"),QStringLiteral("PuBu"),QStringLiteral("YlGnBu"),QStringLiteral("PuBuGn"),QStringLiteral("BuGn"),QStringLiteral("YlGn")}},
        {QStringLiteral("Diverging"),{QStringLiteral("Coolwarm"),QStringLiteral("Bwr"),QStringLiteral("Seismic"),QStringLiteral("Spectral"),QStringLiteral("RdBu"),QStringLiteral("RdGy"),QStringLiteral("RdYlBu"),QStringLiteral("RdYlGn"),QStringLiteral("PuOr"),QStringLiteral("BrBG"),QStringLiteral("PRGn"),QStringLiteral("PiYG")}},
        {QStringLiteral("Cyclic & Angular"),{QStringLiteral("Twilight"),QStringLiteral("Twilight Shifted"),QStringLiteral("HSV"),QStringLiteral("Phase"),QStringLiteral("Cubehelix")}},
        {QStringLiteral("Seasonal & Shading"),{QStringLiteral("Cool"),QStringLiteral("Spring"),QStringLiteral("Summer"),QStringLiteral("Autumn"),QStringLiteral("Winter"),QStringLiteral("Binary"),QStringLiteral("Gist Gray"),QStringLiteral("Gist Yarg")}},
        {QStringLiteral("Terrain, Ocean & Field"),{QStringLiteral("Terrain"),QStringLiteral("Ocean"),QStringLiteral("Gist Earth"),QStringLiteral("Gist Ncar"),QStringLiteral("Gnuplot"),QStringLiteral("Gnuplot2"),QStringLiteral("Nipy Spectral"),QStringLiteral("Rainbow"),QStringLiteral("Gist Rainbow"),QStringLiteral("Jet")}},
        {QStringLiteral("Categorical"),{QStringLiteral("Lines"),QStringLiteral("Tab10"),QStringLiteral("Tab20"),QStringLiteral("Tab20b"),QStringLiteral("Tab20c"),QStringLiteral("Set1"),QStringLiteral("Set2"),QStringLiteral("Set3"),QStringLiteral("Paired"),QStringLiteral("Accent"),QStringLiteral("Dark2"),QStringLiteral("Pastel1"),QStringLiteral("Pastel2")}},
        {QStringLiteral("Specialized & Utility"),{QStringLiteral("Prism"),QStringLiteral("Flag"),QStringLiteral("Colorcube"),QStringLiteral("White")}}
    };
    return cats;
}

inline QStringList names(){
    QStringList out;
    for(const Entry& e:all()) out.append(QString::fromLatin1(e.name));
    return out;
}

// The table for a name, or Viridis for one that is not recognised. A typo in a
// saved figure or a theme should give the default picture, never no picture.
inline const unsigned char (*tableFor(const QString& name))[3] {
    for(const Entry& e:all())
        if(name.compare(QLatin1String(e.name),Qt::CaseInsensitive)==0) return e.table;
    return kViridis;
}

// One sample. NaN is caught before qBound, which would otherwise carry it into
// the index; an unknown cell belongs at the bottom of the map.
inline QColor sample(const unsigned char (*t)[3],double u){
    if(!(u==u)) u=0.0;
    u=qBound(0.0,u,1.0);
    const double pos=u*double(kStops-1);
    int i=int(pos);
    if(i<0) i=0;
    if(i>kStops-2) i=kStops-2;
    const double f=pos-double(i);
    const double r=(t[i][0]*(1.0-f)+t[i+1][0]*f)/255.0;
    const double g=(t[i][1]*(1.0-f)+t[i+1][1]*f)/255.0;
    const double b=(t[i][2]*(1.0-f)+t[i+1][2]*f)/255.0;
    return QColor::fromRgbF(r,g,b);
}

